(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.FunctionLesson,number=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
const cases={square:[[-1,1],[0,0],[1,1]],conflict:[[-1,1],[0,0],[1,1],[1,2]],missing:[[-1,1],[0,0]]};
function relation(){const key=$('[name="relation-case"]:checked').value,pairs=cases[key],result=core.classify([-1,0,1],[0,1,2],pairs);$('#mapping').replaceChildren();for(const [x,y] of pairs){const row=document.createElement('div');math(row,`${x}\\longmapsto ${y}`);$('#mapping').append(row);}$('#relation-feedback').textContent=result.isFunction?'Ini fungsi dari himpunan masukan ke himpunan tujuan yang dinyatakan. Semua masukan mempunyai tepat satu keluaran. Dua masukan boleh berbagi keluaran.':result.conflicts.length?'Ini bukan fungsi: masukan satu mempunyai dua keluaran berbeda, yaitu satu dan dua.':'Ini bukan fungsi dari himpunan masukan yang dinyatakan: masukan satu belum mendapat keluaran.';}
document.querySelectorAll('[name="relation-case"]').forEach(e=>e.addEventListener('change',relation));relation();
const ns='http://www.w3.org/2000/svg';for(let x=-2;x<=2;x++){const p=core.point(x,0),line=document.createElementNS(ns,'line');line.setAttribute('x1',p.x);line.setAttribute('x2',p.x);line.setAttribute('y1',30);line.setAttribute('y2',270);$('#plot-grid').append(line);tick(x,p.x/3,64);}for(let y=-3;y<=5;y++){const p=core.point(0,y),line=document.createElementNS(ns,'line');line.setAttribute('x1',30);line.setAttribute('x2',270);line.setAttribute('y1',p.y);line.setAttribute('y2',p.y);$('#plot-grid').append(line);if(y!==0)tick(y,46,p.y/3);}
function tick(n,left,top){const e=document.createElement('span');e.className='plot-tick';e.dataset.noEquation='';e.textContent=String(n).replace('-','−');e.style.left=left+'%';e.style.top=top+'%';$('#plot-ticks').append(e);}
function draw(){const rule=$('[name="rule"]:checked').value,x=Number($('#function-input').value),y=core.evaluate(rule,x);$('#input-output').value=x;math($('#evaluation'),rule==='linear'?`f(${x})=2\\times(${x})+1=${y}`:`f(${x})=(${x})^2=${y}`);$('#value-table').innerHTML=Array.from({length:5},(_,i)=>i-2).map(a=>`<tr class="${a===x?'selected':''}" ${a===x?'aria-current="true"':''}><td><span data-tex="${a}"></span></td><td><span data-tex="${core.evaluate(rule,a)}"></span></td></tr>`).join('');const commands=[];for(let i=0;i<=80;i++){const a=-2+i/20,p=core.point(a,core.evaluate(rule,a));commands.push(`${i===0?'M':'L'}${p.x} ${p.y}`);}$('#function-curve').setAttribute('d',commands.join(' '));const p=core.point(x,y);$('#function-point').setAttribute('cx',p.x);$('#function-point').setAttribute('cy',p.y);$('#function-plane').setAttribute('aria-label',`Grafik ${rule==='linear'?'f dari x sama dengan dua x ditambah satu':'f dari x sama dengan x kuadrat'}. Titik terpilih memiliki masukan ${x} dan keluaran ${y}.`);$('#function-feedback').innerHTML=`Masukan <span data-tex="${x}"></span> menghasilkan <span data-tex="${y}"></span>. Titik <span data-tex="(${x},${y})"></span> berada pada grafik. `+(rule==='square'?'Coba masukan dengan tanda berlawanan: keluarannya sama.':'Coba masukan berikutnya: keluaran bertambah dua ketika masukan bertambah satu.');}
document.querySelectorAll('[name="rule"]').forEach(e=>e.addEventListener('change',draw));$('#function-input').addEventListener('input',draw);$('#reset-function').addEventListener('click',()=>{$('[name="rule"][value="linear"]').checked=true;$('#function-input').value=1;draw();});draw();
const questions=[{tex:'f(x)=2x+1',prompt:'Berapa keluaran untuk masukan tiga?',n:7,hint:'Ganti variabel dengan tiga, lalu kerjakan perkalian dahulu.',why:'Dua kali tiga ditambah satu menghasilkan tujuh.'},{tex:'g(x)=x^2',prompt:'Berapa keluaran untuk masukan negatif dua?',n:4,hint:'Kuadratkan seluruh masukan, termasuk tanda negatifnya.',why:'Negatif dua dikali negatif dua menghasilkan empat.'},{tex:'f(x)=2x+1',prompt:'Masukan berapa yang menghasilkan keluaran sembilan?',n:4,hint:'Selesaikan persamaan: dua kali masukan ditambah satu sama dengan sembilan.',why:'Kurangi satu lalu bagi dua. Masukan empat menghasilkan sembilan.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=number.parseAnswer($('#answer'+i).value),ok=number.equalAnswer(a,number.rational(q.n));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya 4.':'Belum tepat. Bedakan masukan yang diketahui dan keluaran yang dicari.');}));
const choices=[{prompt:'Dua masukan berbeda mendapat keluaran sama. Apakah hubungan itu masih mungkin merupakan fungsi?',options:['Ya, selama setiap masukan mendapat tepat satu keluaran.','Tidak, semua keluaran harus berbeda.'],answer:0,why:'Syarat fungsi berlaku untuk tiap masukan. Keluaran yang sama boleh dipakai oleh beberapa masukan.'},{prompt:'Dalam suatu relasi, semua anggota domain mendapat keluaran, tetapi satu masukan mendapat dua keluaran berbeda. Apakah ini fungsi?',options:['Ya, karena semua masukan sudah mendapat keluaran.','Tidak, karena satu masukan memiliki dua keluaran berbeda.'],answer:1,why:'Setiap masukan harus memperoleh tepat satu keluaran, bukan dua keluaran berbeda.'},{prompt:'Pada aturan satu dibagi masukan, mengapa nol tidak boleh menjadi anggota domain?',options:['Karena semua masukan fungsi harus positif.','Karena pembagian dengan nol tidak terdefinisi.','Karena keluaran nol tidak diperbolehkan.'],answer:1,why:'Aturan tersebut tidak menghasilkan bilangan real untuk masukan nol. Masukan negatif selain nol tetap diperbolehkan.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input name="choice${i}" type="radio" value="${k}">${o}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p id="feedback${i}" class="feedback" role="status"></p>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-function-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-function-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();